-- Step 7: beta is a natural isomorphism F^flip to G^flip whose components are alpha(Y,X).
flip-bifunctor-NI α = record
  { ⇒ = record
    -- Step 2: define beta by beta(X,Y) = alpha(Y,X). Well-typed since F^flip(X,Y) = F(Y,X), G^flip(X,Y) = G(Y,X).
    { η = λ XY → {!!}
    -- Step 5: naturality of beta. Unfolds to G(g,f) ∘ alpha(Y,X) = alpha(Y',X') ∘ F(g,f), the naturality of alpha at (g, f).
    ; commute = λ fg → {!!}
    }
  ; ⇐ = record
    -- Step 3: the inverse family is beta^-1(X,Y) = alpha^-1(Y,X), the component inverse of alpha at (Y,X).
    { η = λ XY → {!!}
    -- Step 6: naturality of beta^-1. Unfolds to F(g,f) ∘ alpha^-1(Y,X) = alpha^-1(Y',X') ∘ G(g,f), the conclusion of inverseNatural at h = (g, f).
    ; commute = λ fg → {!!}
    }
  -- Step 3: each component beta(X,Y) is an isomorphism. Left inverse law is the left inverse law for alpha(Y,X).
  ; iso = λ XY → record
    { isoˡ = {!!}
    -- Step 3: right inverse law for beta(X,Y) is the right inverse law for alpha(Y,X).
    ; isoʳ = {!!}
